package cl.bolsillo.app;
import android.view.*;import android.widget.*;
final class UpdateScreen {
 static void row(MainActivity a,LinearLayout parent,String title,String subtitle,Runnable action){LinearLayout item=Modern.item(a,"download",title,subtitle,"",Glass.accent(a),action);if(AppUpdates.available(a)){View dot=new View(a);dot.setBackground(Glass.round(a,Glass.AMBER,5));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(a.dp(8),a.dp(8));p.setMargins(a.dp(6),0,a.dp(4),0);item.addView(dot,p);item.setContentDescription(title+". Hay una actualización disponible.");}Modern.add(parent,item,8);}
 static void show(MainActivity a){LinearLayout container=Modern.column(a);a.body.addView(container);Runnable draw=()->{if(!container.isAttachedToWindow()&&container.getParent()==null)return;container.removeAllViews();try{ReleaseFeed.Release release=AppUpdates.release(a);String error=AppUpdates.prefs(a).getString("error","");LinearLayout hero=Modern.surface(a);hero.addView(Icons.badge(a,"download",48),new LinearLayout.LayoutParams(a.dp(48),a.dp(48)));TextView title=Modern.text(a,AppUpdates.downloading?"Descargando… "+AppUpdates.progress+"%":AppUpdates.checking?"Buscando una versión nueva":AppUpdates.ready(a)?"Lista para instalar":AppUpdates.available(a)?"Hay una actualización":!error.isEmpty()?"No se pudo comprobar":AppUpdates.prefs(a).getLong("checked",0)>0?"Tienes la última versión":"Tus actualizaciones",22,Glass.ink(a),true);Modern.add(hero,title,14);Modern.add(hero,Modern.text(a,"Instalada · v"+AppUpdates.installed(a)+(AppUpdates.available(a)?"   →   "+release.version:""),13,Glass.subtle(a),false),8);Modern.add(container,hero,8);
   if(!ReleaseFeed.repository(AppUpdates.repo(a)))Modern.add(container,Modern.text(a,"El repositorio público se está preparando. La actualización no consulta tus cuentas ni tus movimientos.",14,Glass.subtle(a),false),16);
   if(!error.isEmpty())Modern.add(container,Modern.text(a,error,13,Glass.AMBER,false),14);
   if(AppUpdates.available(a)){Button action=Glass.button(a,AppUpdates.ready(a)?"Instalar actualización":"Descargar "+release.version);action.setEnabled(!AppUpdates.downloading);action.setOnClickListener(v->a.attempt(()->{if(AppUpdates.ready(a))AppUpdates.install(a);else AppUpdates.download(a);}));container.addView(action);if(!release.notes.isEmpty()){TextView notes=Modern.text(a,release.notes,14,Glass.subtle(a),false);notes.setMaxLines(16);notes.setEllipsize(android.text.TextUtils.TruncateAt.END);Modern.add(container,notes,18);}}
   Button refresh=Glass.button(a,"Buscar actualizaciones");Icons.Line glyph=new Icons.Line(a,"refresh",0xff17333c);glyph.setBounds(0,0,a.dp(20),a.dp(20));refresh.setCompoundDrawablesRelative(glyph,null,null,null);refresh.setCompoundDrawablePadding(a.dp(8));refresh.setEnabled(!AppUpdates.checking&&!AppUpdates.downloading&&ReleaseFeed.repository(AppUpdates.repo(a)));refresh.setOnClickListener(v->AppUpdates.check(a,true));container.addView(refresh);long checked=AppUpdates.prefs(a).getLong("checked",0);if(checked>0)Modern.add(container,Modern.text(a,"Comprobado "+android.text.format.DateFormat.format("dd/MM · HH:mm",checked),11,Glass.subtle(a),false),8);Modern.add(container,Modern.text(a,"Solo se consulta la versión pública en GitHub. El APK debe tener la misma firma que tu app; Android te pedirá confirmar la instalación.",12,Glass.subtle(a),false),20);
  }catch(Exception e){Modern.add(container,Modern.text(a,"No se pudo mostrar el estado de actualización",14,Glass.subtle(a),false),8);}};draw.run();container.addOnAttachStateChangeListener(new View.OnAttachStateChangeListener(){public void onViewAttachedToWindow(View v){AppUpdates.observe(draw);}public void onViewDetachedFromWindow(View v){AppUpdates.forget(draw);}});}
}
